p("| Rows with MaxScore outside {20, 19, 15} | %d |" % sum(1 for r in pop if r["max"] not in (20, 19, 15)))
p("| Rows with a missing main-window or carried outcome value | %d |" % sum(1 for r in pop if r["ev_main"] != r["ev_main"] or r["ev_C24"] != r["ev_C24"]))
# ledger: attribution points sum to the re-scored raw score on matching rows
led = 0
for r in pop:
    if not r["match"]: continue
    a = attr[r["ts"].strftime("%Y-%m-%d %H:%M:%S")]
    sx = sum(r["pts"][lb][0] for lb in LABELS)
    if sx != r["raw"]: led += 1
p("| Matching rows where the trade side's breakdown points do not sum to the logged raw score (must be 0) | %d |" % led)
era_files = sorted(glob.glob(os.path.join(CACHE, "rescore-eras", "settings-v*.json")))
if era_files:
    keyvals = defaultdict(set)
    for fpath in era_files:
        e = json.load(open(fpath, encoding="utf-8-sig"))
        for path_, getter in [("verdict pcts", lambda e: (e["scoring"]["verdict_strong_pct"], e["scoring"]["verdict_med_pct"], e["scoring"]["verdict_weak_pct"])),
                              ("squeeze", lambda e: e["scoring"]["bbw_squeeze_penalty"]), ("decel", lambda e: e["indicators"]["MicroCVD"]["decel_penalty"]),
                              ("cvd div", lambda e: e["indicators"]["CVD"]["divergence_penalty"]), ("oicvd", lambda e: (e["indicators"]["oi_cvd_cross"]["upgrade_bonus"], e["indicators"]["oi_cvd_cross"]["conflict_penalty"])),
                              ("burst", lambda e: (e["indicators"]["aggressor_velocity"]["upgrade_bonus"], e["indicators"]["aggressor_velocity"]["contra_penalty"])),
                              ("p2c", lambda e: (e["regime_weights"]["trending"]["alignment_bonus"], e["regime_weights"]["trending"]["conflict_penalty"], e["regime_weights"]["range_bound"]["alignment_bonus"], e["regime_weights"]["range_bound"]["conflict_penalty"])),
                              ("ts", lambda e: e["indicators"]["trend_structure"]["structure_bonus"]), ("spread", lambda e: e["scoring"]["spread_wide_penalty"]),
                              ("funding", lambda e: (e["scoring"]["funding_high_penalty"], e["scoring"]["funding_high_boost"], e["scoring"]["funding_low_penalty"], e["indicators"]["funding"]["momentum_amplify"], e["indicators"]["funding"]["momentum_soften"]))]:
            keyvals[path_].add(json.dumps(getter(e)))
    changed = [k for k, v in keyvals.items() if len(v) > 1]
    p("| Era settings files read / magnitude groups that differ between eras (must be none) | %d / %s |" % (len(era_files), ", ".join(changed) if changed else "none"))
p()
p("| Session | Rows | STRONG | MEDIUM | WEAK | H1 rows | H2 rows | Trading days |")
p("|---|---|---|---|---|---|---|---|")
for s in SESSIONS:
    sr = sess_rows(s)
    c = Counter(r["tier"] for r in sr)
    p("| %s | %d | %d | %d | %d | %d | %d | %d |" % (s, len(sr), c["STRONG"], c["MEDIUM"], c["WEAK"], sum(1 for r in sr if r["half"] == "H1"), sum(1 for r in sr if r["half"] == "H2"), len(set(r["day"] for r in sr))))
p()

# Baseline tier gaps (reference for every later section)
p("## 1. Baseline: tier outcomes and the tier gap per session")
p()
for m, *_ in MODES:
    p("### 1.%d %s" % (1 if m == "main" else 2, "main window" if m == "main" else "carried 24 h"))
    p()
    p("| Session | Tier | n | Success % | Net EV [95 % CI] |")
    p("|---|---|---|---|---|")
    for s in SESSIONS:
        for t in TIERS:
            p("| %s | %s | %s |" % (s, t, cell_stats([r for r in sess_rows(s) if r["tier"] == t], m)))
    p()
    p("| Session | Comparison " + CMP_HDR)
    p("|---|---|---|---|---|---|")
    for s in SESSIONS:
        sr = sess_rows(s)
        for a_, b_ in [("MEDIUM", "WEAK"), ("MEDIUM", "STRONG")]:
            res, lab = compare(sr, lambda r, a_=a_: r["tier"] == a_, lambda r, b_=b_: r["tier"] == b_, lambda r, m=m: r["ev_" + m],
                               "%s - %s" % (a_, b_), "1 baseline %s %s" % (m, s))
            p("| %s | %s - %s | %s |" % (s, a_, b_, cmp_row(res, lab)))
    p()

# ================================================================== D-1
p("## 2. D-1: is the score monotone in quality?")
