SHARE_BINS = [(0.0, 0.45, "< 0.45"), (0.45, 0.53, "0.45-0.53"), (0.53, 0.60, "0.53-0.60"), (0.60, 0.70, "0.60-0.70"), (0.70, 9.0, ">= 0.70")]
