def slope_stat(s, c):
    n = c[0]
    if n < 3: return float("nan")
    sx, sy, sxy, sxx = s[1], s[2], s[3], s[4]
    den = n * sxx - sx * sx
    return (n * sxy - sx * sy) / den if den > 0 else float("nan")
for m, *_ in MODES:
    for feat, bins, scale, fname in [("share", SHARE_BINS, 10.0, "effective score share of regime max (slope per 0.1)"), ("margin", MARGIN_BINS, 1.0, "effective margin, dominant minus opposite (slope per point)")]:
        p("### D-1 %s, %s" % (fname.split(" (")[0], "main window" if m == "main" else "carried 24 h"))
        p()
        p("| Session | Bin | n | Success % | Net EV [95 % CI] | H1 EV | H2 EV |")
        p("|---|---|---|---|---|---|---|")
        for s in SESSIONS:
            sr = sess_rows(s)
            for lo, hi, nm in bins:
                cell = [r for r in sr if lo <= r[feat] < hi]
                h1 = [r["ev_" + m] for r in cell if r["half"] == "H1"]; h2 = [r["ev_" + m] for r in cell if r["half"] == "H2"]
                p("| %s | %s | %s | %s | %s |" % (s, nm, cell_stats(cell, m), f1(sum(h1) / len(h1)) if h1 else "n/a", f1(sum(h2) / len(h2)) if h2 else "n/a"))
        p()
        p("| Session | Statistic " + CMP_HDR)
        p("|---|---|---|---|---|---|")
        for s in SESSIONS:
            sr = sess_rows(s)
            contribs = lambda r, m=m, feat=feat, scale=scale: [(0, 0.0), (1, r[feat] * scale), (2, r["ev_" + m]), (3, r[feat] * scale * r["ev_" + m]), (4, (r[feat] * scale) ** 2)]
            res = {hn: boot(hr, contribs, 5, slope_stat) for hn, hr in halves(sr).items()}
            lab = label(res, (0,))
            ALL_LABELS.append(("2 D-1 %s %s %s" % (feat, m, s), "OLS slope", lab, res["FULL"]))
            p("| %s | slope of net EV on %s | %s |" % (s, fname, cmp_row(res, lab, (0,))))
        p()

