def within_tier_contribs(lb, m):
    def cb(r):
        t = TIERS.index(r["tier"])
        if r["lean"][lb] > 0: return [(2 * t, r["ev_" + m])]
        if r["lean"][lb] < 0: return [(2 * t + 1, r["ev_" + m])]
        return []
    return cb

def within_tier_stat(s, c):
    num = 0.0; w = 0
    for t in range(3):
        if c[2 * t] > 0 and c[2 * t + 1] > 0:
            wt = c[2 * t] + c[2 * t + 1]
            num += wt * (s[2 * t] / c[2 * t] - s[2 * t + 1] / c[2 * t + 1]); w += wt
    return num / w if w > 0 else float("nan")

