# applied delta on the trade side, per mutation family
def applied(r, fam):
    X = r["xs"]
    ms = r["mutset"]
    if fam == "SQUEEZE_PEN":
        return r["pts"]["BBW_TTM"][0] if "SQUEEZE_PEN" in ms else 0
    if fam in ("DECEL_PEN", "STALL_PEN"):
        return r["pts"]["MICROCVD"][0] if (fam + "_" + X) in ms else 0
    if fam == "CVD_DIV_PEN":
        return r["pts"]["CVD"][0] if ("CVD_DIV_PEN_" + X) in ms else 0
    if fam == "SPREAD_PEN":
        return r["pts"]["SPREAD"][0] if ("SPREAD_PEN_" + X) in ms else 0
    if fam == "P2C_ALIGN":
        return r["pts"]["REGIME_ALIGN"][0] if ("P2C_ALIGN_" + X) in ms else 0
    if fam == "P2C_CONFLICT":
        return r["pts"]["REGIME_ALIGN"][0] if ("P2C_CONFLICT_" + X) in ms else 0
    if fam == "TS_BONUS":
        return r["pts"]["TREND_STRUCTURE"][0] if ("TS_BONUS_" + X) in ms else 0
    if fam == "FUNDING_STEP3_3B":
        return r["pts"]["FUNDING"][0]
    if fam in ("RSI_DIV_PEN", "OICVD_CONFIRM", "OICVD_CONFLICT", "BURST_CONFIRM", "BURST_CONTRA"):
        return NOM[fam] if (fam + "_" + X) in ms else 0
    if fam == "PASS2_UPGRADES":
        return sum(1 for mm in ms if mm.endswith("_UPGRADE_" + X))
    if fam == "TRANSITIONAL_ADX_PENALTY":
        return -r["pen"]
    raise KeyError(fam)

