def fund_nominal(r, side):
    tot = 0
    for mm in r["muts"]:
        if mm.startswith("STEP3"):
            for val, sd in re.findall(r"([+-]\d+)\[([LS])\]", mm):
                if sd == side: tot += int(val)
    return tot
def binds(r, side_idx):
    """Return list of binding kinds on the trade side (side_idx 0) or the other side (1)."""
    sd = r["xs"] if side_idx == 0 else r["ys"]
    ms = r["mutset"]; b = []
    pts = lambda lb: r["pts"][lb][side_idx]
    if "SQUEEZE_PEN" in ms and pts("BBW_TTM") > NOM["SQUEEZE_PEN"]: b.append("squeeze clamp")
    if ("DECEL_PEN_" + sd) in ms and pts("MICROCVD") > NOM["DECEL_PEN"]: b.append("decel clamp")
    if ("STALL_PEN_" + sd) in ms and pts("MICROCVD") > NOM["STALL_PEN"]: b.append("stall clamp")
    if ("CVD_DIV_PEN_" + sd) in ms and pts("CVD") > NOM["CVD_DIV_PEN"]: b.append("CVD divergence clamp")
    if ("SPREAD_PEN_" + sd) in ms and pts("SPREAD") > NOM["SPREAD_PEN"]: b.append("spread clamp")
    if ("P2C_CONFLICT_" + sd) in ms and pts("REGIME_ALIGN") > NOM["P2C_CONFLICT"]: b.append("Pass 2c conflict clamp")
    if ("P2C_ALIGN_" + sd) in ms and pts("REGIME_ALIGN") < NOM["P2C_ALIGN"]: b.append("Pass 2c align cap")
    if ("TS_BONUS_" + sd) in ms and pts("TREND_STRUCTURE") < NOM["TS_BONUS"]: b.append("trend structure cap")
    fn = fund_nominal(r, sd)
    if fn != pts("FUNDING"): b.append("funding clamp or cap")
    return b
fund_bad = 0
for a in attr.values():
    if a["MatchSix"] != "1": continue
    for sd in "LS":
        nom = 0
        for mm in a["Mutations"].split(";"):
            if mm.startswith("STEP3"):
                for val, s2 in re.findall(r"([+-]\d+)\[([LS])\]", mm):
                    if s2 == sd: nom += int(val)
        if nom != inum(a["FUNDING_" + sd]) and inum(a["LongScore" if sd == "L" else "ShortScore"]) > 1: fund_bad += 1
p("- Parser check: matching trading-week sides where the funding points differ from the note's nominal AND the final raw score is above 1 (a clamp at 0 plus a Step 3b soften cannot explain these; must be 0): %d." % fund_bad)
p()
p("| Session | Tier | Rows | Trade side: rows with a binding clamp or cap (%) | Other side: rows with a binding clamp or cap (%) | Trade-side raw score = regime max (a cap could bind) | Binding kinds, trade side | Binding kinds, other side |")
p("|---|---|---|---|---|---|---|---|")
for s in SESSIONS:
    for t in TIERS:
        c = [r for r in pop if r["session"] == s and r["tier"] == t]
        k0, k1 = Counter(), Counter()
        n0 = n1 = 0
        for r in c:
            b0 = binds(r, 0); b1 = binds(r, 1)
            if b0: n0 += 1
            if b1: n1 += 1
            k0.update(b0); k1.update(b1)
        p("| %s | %s | %d | %d (%.1f) | %d (%.1f) | %d | %s | %s |" % (s, t, len(c), n0, 100.0 * n0 / max(1, len(c)), n1, 100.0 * n1 / max(1, len(c)), sum(1 for r in c if r["raw"] >= r["max"]),
            "; ".join("%s %d" % kv for kv in k0.most_common()) or "none", "; ".join("%s %d" % kv for kv in k1.most_common()) or "none"))
